css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.ls53-widget {
  --ls53-metal: #D7D8DB;
  --ls53-outline: #4E4E4E;
  --ls53-liquid: #A0CFE9;
  --ls53-fiber: #0A638F;
  --ls53-steam: #930606;
  --ls53-condensate: #4E4E4E;
  --ls53-control: #01524F;
  --ls53-valve: #0E0E55;
  --ls53-text: #000000;

  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  font-family: "Segoe UI", Arial, sans-serif;
  pointer-events: none;
}

.ls53-widget,
.ls53-widget * {
  box-sizing: border-box;
  animation: none !important;
  transition: none !important;
}

.ls53-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  shape-rendering: geometricPrecision;
}

.ls53-metal-stop {
  stop-color: var(--ls53-metal);
}

.ls53-liquid-stop {
  stop-color: var(--ls53-liquid);
}

/* Cubas. */

.ls53-tank {
  filter: url("#ls53-tank-shadow");
}

.ls53-tank-body {
  fill: url("#ls53-tank-metal");
  stroke: var(--ls53-outline);
  stroke-width: 1.8;
  stroke-linejoin: round;
}

.ls53-tank-liquid {
  fill: url("#ls53-liquid-gradient");
  stroke: none;
}

.ls53-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 0.7;
  stroke-linecap: round;
  opacity: 0.48;
}

.ls53-tank-shade {
  fill: none;
  stroke: #555D69;
  stroke-width: 0.65;
  stroke-linecap: round;
  opacity: 0.16;
}

/* Tuberías. */

.ls53-steam,
.ls53-condensate,
.ls53-control,
.ls53-aux-line {
  fill: none;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

.ls53-steam {
  stroke: var(--ls53-steam);
}

.ls53-condensate {
  stroke: var(--ls53-condensate);
}

.ls53-control {
  stroke: var(--ls53-control);
}

.ls53-aux-line {
  stroke: var(--ls53-fiber);
}

.ls53-main {
  stroke-width: 2;
}

.ls53-valve-connection {
  stroke-linecap: butt;
}

.ls53-control-node {
  fill: var(--ls53-control);
  stroke: none;
}

/* Válvulas transparentes. */

.ls53-valve-body {
  fill: none;
  stroke: var(--ls53-valve);
  stroke-width: 1.4;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.ls53-valve-stem {
  fill: none;
  stroke: var(--ls53-valve);
  stroke-width: 0.7;
  stroke-linecap: butt;
}

.ls53-valve-actuator {
  fill: var(--ls53-valve);
  stroke: var(--ls53-valve);
  stroke-width: 1;
}

/* Cuerda. */

.ls53-fiber {
  fill: none;
  stroke: var(--ls53-fiber);
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

/* Poleas. */

.ls53-roller-body {
  fill: url("#ls53-roller-metal");
  stroke: var(--ls53-outline);
  stroke-width: 2.2;
  filter: url("#ls53-roller-shadow");
}

.ls53-roller-number {
  fill: var(--ls53-text);
  stroke: none;

  font-family: "IBM Plex Mono", Consolas, monospace;
  font-size: 13px;
  font-weight: 700;

  text-anchor: middle;
  dominant-baseline: middle;
}

/* Conjunto vertical derecho. */

.ls53-hardware {
  fill: url("#ls53-hardware-metal");
  stroke: var(--ls53-outline);
  stroke-width: 1;
  stroke-linejoin: round;
}

.ls53-hardware-detail {
  fill: none;
  stroke: var(--ls53-outline);
  stroke-width: 1;
  stroke-linecap: round;
}

.ls53-hardware-shadow {
  filter: url("#ls53-roller-shadow");
}

.ls53-aux-arrow {
  fill: var(--ls53-fiber);
  stroke: none;
}

/* Textos. */

.ls53-label {
  fill: var(--ls53-text);
  stroke: none;
  font-size: 13px;
  font-weight: 700;
}

.ls53-steam-label,
.ls53-condensate-label {
  stroke: none;
  font-size: 12px;
  font-weight: 600;
}

.ls53-steam-label {
  fill: var(--ls53-steam);
}

.ls53-condensate-label {
  fill: var(--ls53-condensate);
}

.ls53-footer {
  fill: var(--ls53-text);
  stroke: none;
  font-size: 16px;
  font-style: italic;
  font-weight: 500;
  text-anchor: end;
}

